WITH flattened AS (SELECT id, host, log_ts, level, latency_ms, attr_key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, value) SELECT latency_ms, attr_key, value, CUME_DIST() OVER (ORDER BY latency_ms NULLS FIRST) AS latency_ms_cume_dist, CUME_DIST() OVER (PARTITION BY attr_key, level ORDER BY latency_ms DESC NULLS FIRST) AS latency_ms_cume_dist_2, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY attr_key), 4) AS latency_ms_share, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY level), 4) AS latency_ms_share_2 FROM flattened WHERE host = 'h1';
